package org.kanger.storage.dumb2;
import java.nio.file.*;
import java.util.*;
import java.util.concurrent.atomic.AtomicBoolean;
import org.kanger.*;
import org.kanger.ContextSignedModelInspection.*;
import org.kanger.ContextSignedModelInspection.Result;
import org.kanger.exception.*;
import org.kanger.enums.StorageLifecycleErrorCode;
final class ContextSignedLiveModelMatrix {
 static int checks;static final int WORK=64000000;
 static void require(boolean b,String why){checks++;if(!b)throw new AssertionError(why);}
 interface Attempt{void run()throws Exception;}
 static void reject(Attempt a,String why)throws Exception{boolean failed=false;try{a.run();}catch(Exception expected){failed=true;}require(failed,why);}
 static Limits limits(){return limits(512,WORK,WORK,WORK);}
 static Limits limits(int candidates,int originalAudit,int finalAudit,int nativeAudit){ContextSignedCandidateInspection.Limits n=new ContextSignedCandidateInspection.Limits(64,8,2,16,WORK,500000,WORK,nativeAudit,64);return new Limits(n,candidates,16,8,WORK,16,64,originalAudit,16,16,8,WORK,65536,finalAudit);}
 static SemanticTermSnapshot value(int n)throws Exception{Mind m=new Mind(new User());require(m.compile("!basis("+n+");",null,false),"ordinary admissible basis fixture");ContextProductionInventory i=ContextProductionInventory.inspect(m,UUID.randomUUID(),0,true,Collections.emptyList(),64);ContextProductionNativeBinding.Result b=ContextProductionNativeBinding.bind(m,i,WORK,500000);if(!b.bound)throw new AssertionError(b.reason);return b.snapshot.primary.get(0).clauses.get(0).literals.get(0).arguments.get(0).value;}
 static String fp(ContextNativeCandidateLeaseMatrix.Fixture f,Mind m)throws Exception{return ContextProductionInventory.inspect(m,f.db.getContextId(),f.db.getRevision(),true,Collections.emptyList(),64).fingerprint;}
 static void yes(Result r){require(r.status==Status.MODELLED_SUPPLIED&&r.proposed!=null&&r.oppositions.isEmpty(),r.phase+": "+r.reason);require(r.originalCandidates>0&&r.validOriginals>0&&r.extensionCandidates>0&&r.originalRows>0&&r.finalObligations>0&&r.namedPoints==1,"complete original+actual-final chain diagnostic counts");}
 static void no(Result r){require(r.status==Status.INCOMPLETE&&r.proposed==null&&r.foreign.isEmpty()&&r.oppositions.isEmpty()&&r.originalCandidates==0&&r.validOriginals==0&&r.extensionCandidates==0&&r.originalRows==0&&r.finalObligations==0&&r.namedPoints==0,"atomic INCOMPLETE, no model/proof prefix or refutation from failed search: "+r.reason);}
 static void positive()throws Exception{
  Path d=Files.createTempDirectory("signed-live-model-");ContextNativeCandidateLeaseMatrix.create(d,"A","!$u seed(u)&&~blocked(u);");SemanticTermSnapshot one=value(1);try(ContextNativeCandidateLeaseMatrix.Fixture f=new ContextNativeCandidateLeaseMatrix.Fixture(d,"X")){require(f.mind.compile("!anchor(1);",null,false),"root");f.db.connectContext("A");long revision=f.db.getRevision();String parent=fp(f,f.mind);Mind child=new Mind(f.mind);try{require(child.compile("!@u seed(u)->~blocked(u);",null,false),"prepared actual signed child");List<SemanticTermSnapshot> basis=new ArrayList<>(Collections.singletonList(one));Result r=f.db.inspectSignedModelPendingProduction(child,basis,limits());yes(r);require(r.proposed.fingerprint.equals(fp(f,child))&&r.foreign.size()==1&&r.foreign.get(0).members.size()==1,"exact actual child and initialized physical member metadata");require(r.originalRows==3,"complete original physical row count");basis.clear();require(r.namedPoints==1,"caller basis detached");Result again=f.db.inspectSignedModelPendingProduction(child,Collections.singletonList(one),limits());yes(again);require(again!=r&&again.proposed.fingerprint.equals(r.proposed.fingerprint),"fresh actual operation, no diagnostic result authority input");reject(()->r.foreign.clear(),"immutable logical cuts");reject(()->r.foreign.get(0).members.clear(),"immutable physical members");reject(()->r.foreign.get(0).members.get(0).initialization.clear(),"immutable initialized view metadata");reject(()->r.oppositions.clear(),"immutable diagnostic oppositions");boolean receipt=false;for(java.lang.reflect.Field field:Result.class.getDeclaredFields())receipt|=field.getType().getName().contains("Receipt");require(!receipt,"no sealed receipt or live model authority escapes public metadata");ContextSignedCommitException old=null;try{f.db.validatePendingSignedProductionCommit(child,limits().nativeLimits,WORK,WORK,1000000);}catch(ContextSignedCommitException expected){old=expected;}require(old!=null&&old.getErrorCode()==StorageLifecycleErrorCode.STORAGE_CONTEXT_INCOMPLETE&&old.getPhase().equals("full-family-qualification"),"successful model diagnostic does NOT select/bypass existing writer gate");require(f.db.getRevision()==revision&&parent.equals(fp(f,f.mind))&&f.user.getCurrentMind()==f.mind&&f.user.getData()==f.db,"read-only public API, actual provider/caller unchanged");}finally{f.mind.release(child);}}
  ContextNativeCandidateLeaseMatrix.create(d,"P","!p(1);");ContextNativeCandidateLeaseMatrix.create(d,"N","!~p(1);");for(boolean reverse:new boolean[]{false,true})try(ContextNativeCandidateLeaseMatrix.Fixture f=new ContextNativeCandidateLeaseMatrix.Fixture(d,"Order"+reverse)){require(f.mind.compile("!~anchor(1);",null,false),"negative root");f.db.connectContext(reverse?"N":"P");f.db.connectContext(reverse?"P":"N");Mind child=new Mind(f.mind);try{Result r=f.db.inspectSignedModelPendingProduction(child,Collections.singletonList(one),limits());yes(r);require(r.foreign.size()==2&&r.foreign.stream().allMatch(c->c.trustedGroup==null&&c.members.size()==1),"independent contradictory members MODELLED in both orders without communalization");}finally{f.mind.release(child);}}
  ContextNativeCandidateLeaseMatrix.create(d,"Q","!~q(1);");try(ContextNativeCandidateLeaseMatrix.Fixture f=new ContextNativeCandidateLeaseMatrix.Fixture(d,"Trusted")){require(f.mind.compile("!~anchor(1);",null,false),"trusted root");f.db.connectContext("P","own");f.db.connectContext("Q","own");Mind child=new Mind(f.mind);try{Result r=f.db.inspectSignedModelPendingProduction(child,Collections.singletonList(one),limits());yes(r);require(r.foreign.size()==1&&"own".equals(r.foreign.get(0).trustedGroup)&&r.foreign.get(0).members.size()==2&&r.originalRows==3,"actual qualified TRUST one cut, BOTH original physical members");}finally{f.mind.release(child);}}
  System.out.println("SIGNED_LIVE_MODEL_POSITIVE actualPublicDbApi=true completeOriginalAndFinal=true independentOrders=2 wholeTrust=true noWriterSelection=true");
 }
 static List<SemanticTermSnapshot> duringCopy(SemanticTermSnapshot point,Attempt mutation,AtomicBoolean fired){return new AbstractList<SemanticTermSnapshot>(){public int size(){return 1;}public SemanticTermSnapshot get(int i){if(i!=0)throw new IndexOutOfBoundsException();if(fired.compareAndSet(false,true))try{mutation.run();}catch(Exception e){throw new IllegalStateException(e);}return point;}};}
 static void freshness()throws Exception{
  Path d=Files.createTempDirectory("signed-live-model-current-");ContextNativeCandidateLeaseMatrix.create(d,"A","!$u seed(u);");SemanticTermSnapshot one=value(1);try(ContextNativeCandidateLeaseMatrix.Fixture f=new ContextNativeCandidateLeaseMatrix.Fixture(d,"X")){require(f.mind.compile("!anchor(1);",null,false),"root");f.db.connectContext("A");long revision=f.db.getRevision();String parent=fp(f,f.mind);Mind child=new Mind(f.mind);try{require(child.compile("!@u seed(u)->~blocked(u);",null,false),"actual child");try(ContextPendingProductionSnapshotSession lease=ContextPendingProductionSnapshotSession.open(f.db,child,64)){Result old=lease.inspectSignedModel(Collections.singletonList(one),limits());yes(old);AtomicBoolean fired=new AtomicBoolean();Result[] escaped={null};List<SemanticTermSnapshot> changing=duringCopy(one,()->f.db.applyConnectionCommand(f.mind,"A","!@u seed(u)->blocked(u);"),fired);reject(()->escaped[0]=lease.inspectSignedModel(changing,limits()),"POST-work guard rejects changed initialized view even when old bound model computes");require(fired.get()&&escaped[0]==null,"deterministic real mid-operation initialized edit, no result prefix escapes finally");require(f.db.getRevision()==revision&&parent.equals(fp(f,f.mind)),"same physical X revision+inventory not sufficient");reject(()->lease.inspectSignedModel(Collections.singletonList(one),limits()),"PRE-work guard rejects stale initialized member");Result fresh=f.db.inspectSignedModelPendingProduction(child,Collections.singletonList(one),limits());require(fresh.status==Status.REFUTED&&fresh.proposed!=null&&fresh.oppositions.stream().anyMatch(o->o.sources.size()==3)&&fresh.originalCandidates==0&&fresh.finalObligations==0,"fresh API returns actual audited three-Source proof, not search failure");require(old.status==Status.MODELLED_SUPPLIED&&!old.foreign.get(0).members.get(0).fingerprint.equals(fresh.foreign.get(0).members.get(0).fingerprint),"old metadata historical, new operation recaptures actual foreign view");}}finally{f.mind.release(child);}}
  try(ContextNativeCandidateLeaseMatrix.Fixture f=new ContextNativeCandidateLeaseMatrix.Fixture(d,"Child")){require(f.mind.compile("!anchor(1);",null,false),"root");long revision=f.db.getRevision();String parent=fp(f,f.mind);Mind child=new Mind(f.mind);try{require(child.compile("!p(1);",null,false),"prepared child");Result old=f.db.inspectSignedModelPendingProduction(child,Collections.singletonList(one),limits());yes(old);AtomicBoolean fired=new AtomicBoolean();Result[] escaped={null};List<SemanticTermSnapshot> changing=duringCopy(one,()->{if(!child.compile("!q(1);",null,false))throw new AssertionError("child mutation");},fired);reject(()->escaped[0]=f.db.inspectSignedModelPendingProduction(child,changing,limits()),"public API POST-work guard rejects actual child mutation");require(fired.get()&&escaped[0]==null,"real child changed after binding, no historical success escapes");Result fresh=f.db.inspectSignedModelPendingProduction(child,Collections.singletonList(one),limits());yes(fresh);require(!old.proposed.fingerprint.equals(fresh.proposed.fingerprint),"fresh whole child recaptured");require(f.db.getRevision()==revision&&parent.equals(fp(f,f.mind)),"no pending publication");}finally{f.mind.release(child);}}
  System.out.println("SIGNED_LIVE_MODEL_CURRENTNESS preAndPostWork=true deterministicActualMutations=true childAndInitializedViews=true freshRefutation=true noEscapedPrefix=true");
 }
 static void boundary()throws Exception{
  Path d=Files.createTempDirectory("signed-live-model-boundary-");SemanticTermSnapshot one=value(1),two=value(2);try(ContextNativeCandidateLeaseMatrix.Fixture f=new ContextNativeCandidateLeaseMatrix.Fixture(d,"X")){require(f.mind.compile("!anchor(1);",null,false),"root");long revision=f.db.getRevision();String parent=fp(f,f.mind);Mind child=new Mind(f.mind);try{require(child.compile("!p(1);",null,false),"prepared child");no(f.db.inspectSignedModelPendingProduction(child,Collections.singletonList(one),limits(1,WORK,WORK,WORK)));no(f.db.inspectSignedModelPendingProduction(child,Collections.emptyList(),limits()));no(f.db.inspectSignedModelPendingProduction(child,null,limits()));no(f.db.inspectSignedModelPendingProduction(child,Arrays.asList(one,one),limits()));no(f.db.inspectSignedModelPendingProduction(child,Collections.singletonList(two),limits()));no(f.db.inspectSignedModelPendingProduction(child,Collections.singletonList(one),limits(512,1,WORK,WORK)));no(f.db.inspectSignedModelPendingProduction(child,Collections.singletonList(one),limits(512,WORK,1,WORK)));no(f.db.inspectSignedModelPendingProduction(child,Collections.singletonList(one),limits(512,WORK,WORK,1)));
   ContextPendingProductionSnapshotSession closed=ContextPendingProductionSnapshotSession.open(f.db,child,64);closed.close();reject(()->closed.inspectSignedModel(Collections.singletonList(one),limits()),"closed lease");try(ContextPendingProductionSnapshotSession lease=ContextPendingProductionSnapshotSession.open(f.db,child,64)){AtomicBoolean refused=new AtomicBoolean();Thread thread=new Thread(()->{try{lease.inspectSignedModel(Collections.singletonList(one),limits());}catch(Exception expected){refused.set(true);}});thread.start();thread.join();require(refused.get(),"owner thread enforced by new diagnostic path");}
   reject(()->f.db.inspectSignedModelPendingProduction(f.mind,Collections.singletonList(one),limits()),"parent cannot impersonate actual child");require(child.compile("!@u binary(u,u);",null,false),"unsupported unary-model shape fixture");no(f.db.inspectSignedModelPendingProduction(child,Collections.singletonList(one),limits()));require(f.db.getRevision()==revision&&parent.equals(fp(f,f.mind)),"invalid/bounded diagnostics leave physical state unchanged");
  }finally{f.mind.release(child);}}
  System.out.println("SIGNED_LIVE_MODEL_BOUNDARY atomicIncomplete=true noConflictFromSearch=true explicitBasisAndAudits=true ownerLifecycle=true unsupportedNoAdmission=true");
 }
}
